contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address to, uint256 amount) public payable {
        require(true);
        // Fresh pool: this contract holds zero shares.
        uint256 balSender = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 balTo = c.balanceOf(to); if (__ESBMC_reverted()) return;

        bool reverted;
        // top-level state-changing call
        c.transfer(to, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balSenderAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 balToAfter = c.balanceOf(to); if (__ESBMC_reverted()) return;

        // General rule: transfer reverts iff amount exceeds the sender's balance;
        // when it succeeds it moves exactly `amount` of shares from sender to `to`.
        assert(
            (reverted && amount > balSender)
            ||
            (!reverted && amount <= balSender
                && balToAfter == balTo + amount
                && balSenderAfter + amount == balSender)
        );
    }

    receive() external payable {}
}

